const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const freeMode=()=>$('#run-mode').value==='free';
let problems=[],current,onlySolved=false,activeTab='description',worker=null,busy=false;
let state={drafts:{},solved:{},fixtures:{},history:{}};
try{state={...state,...JSON.parse(localStorage.getItem('sqllab-v1')||'{}')}}catch{}
const esc=v=>String(v??'NULL').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function toast(s){$('#toast').textContent=s;$('#toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').style.display='none',3000)}
function persist(){try{localStorage.setItem('sqllab-v1',JSON.stringify(state))}catch{toast('Bộ nhớ thiết bị đã đầy. Hãy sao chép code để lưu lại.')}}
function updateProgress(){const n=Object.keys(state.solved).filter(id=>problems.some(p=>p.id===id&&p.verified)).length;const total=problems.filter(p=>p.verified).length;$('#solved-count').textContent=n;$('#total-solved').textContent=n;$('#ready-count').textContent=total;$('#progress-label').textContent=`${n} / ${total}`;$('#progress').style.width=(n/total*100||0)+'%'}
function renderList(){let q=$('#search').value.trim().toLocaleLowerCase('vi');const folded=s=>s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/đ/g,'d');const list=problems.filter(p=>(!q||folded(p.id+' '+p.title).toLowerCase().includes(folded(q)))&&(!$('#difficulty').value||p.difficulty===$('#difficulty').value)&&(!$('#kind').value||p.type===$('#kind').value)&&(!$('#ready').checked||p.verified)&&(!onlySolved||state.solved[p.id]));$('#list-count').textContent=list.length+' bài';$('#problem-list').innerHTML=list.map(p=>`<button class="problem-item ${p.id===current?.id?'selected':''}" data-id="${p.id}" aria-current="${p.id===current?.id}"><div class="problem-meta"><span>${state.solved[p.id]?'✓':p.verified?'◉':'○'}</span>${p.id}<span class="difficulty ${p.difficulty.toLowerCase()}">${p.difficulty}</span></div><div class="problem-name">${esc(p.title)}</div><div class="problem-ready">${p.verified?'Có ví dụ để chấm':p.type+' · Đề & lời giải'}</div></button>`).join('')||'<p class="muted" style="padding:15px">Không tìm thấy bài phù hợp.</p>';$$('.problem-item').forEach(b=>b.onclick=()=>select(b.dataset.id))}
function showTab(name){activeTab=name;$$('.tabs button').forEach(b=>{b.classList.toggle('selected',b.dataset.tab===name);b.setAttribute('aria-selected',b.dataset.tab===name)});$$('.tab-content').forEach(el=>el.hidden=el.id!==name);if(name==='history')history()}
function table(r){if(!r)return '';return `<div style="overflow:auto"><table><thead><tr>${r.columns.map(c=>`<th>${esc(c)}</th>`).join('')}</tr></thead><tbody>${r.values.map(row=>`<tr>${row.map(v=>`<td>${esc(v)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>${!r.values.length?'<p class="muted">0 dòng</p>':''}`}
function schema(){const p=current;$('#schema').innerHTML=p.tables.map(t=>`<h4>${esc(t.name)} <small>(${t.values.length} dòng)</small></h4>`+table(t)).join('')||'<p class="muted">Sơ đồ bảng có trong đề bài. Nhập dữ liệu khởi tạo phía trên để chạy thử.</p>'}
function lineNumbers(){$('#line-numbers').textContent=Array.from({length:$('#code').value.split('\n').length},(_,i)=>i+1).join('\n');$('#line-numbers').scrollTop=$('#code').scrollTop}
function defaultCode(p){return `-- ${p.id} · ${p.title}\n-- Viết truy vấn của bạn tại đây\n\nSELECT \n  \nFROM ;`}
function select(id){$('#run-mode').value='problem';const p=problems.find(p=>p.id===id);if(!p)return;if(worker){worker.terminate();worker=null;setBusy(false)}current=p;location.hash=p.id;$('#problem-code').textContent=p.id+' / '+p.type;$('#position').textContent=p.number+' / '+problems.length;$('#problem-title').textContent=p.title;$('#badges').innerHTML=`<span class="badge ${p.difficulty.toLowerCase()}">${p.difficulty}</span><span class="badge">${p.type}</span><span class="badge">${p.verified?'◉ Có ví dụ để chấm':'Đề gốc từ repository'}</span>`;$('#description').innerHTML=p.html;$('#description').insertAdjacentHTML('afterbegin',`<div class="notice">${p.verified?'Chấm trên dữ liệu ví dụ công khai trong đề; repo không cung cấp test ẩn.':esc(p.reason)}</div>`);$('#solution-code').textContent=p.answer;$('#code').value=state.drafts[p.id]??defaultCode(p);$('#fixture').value=state.fixtures[p.id]??p.setup;$('#execution-time').textContent='';$('#result').innerHTML='<div class="empty-state"><div>⌘</div><h3>Sẵn sàng cho truy vấn đầu tiên?</h3><p>Viết câu lệnh SQL, rồi chọn <b>Chạy thử</b><br>để xem kết quả trên dữ liệu ví dụ.</p></div>';lineNumbers();schema();showTab('description');renderList();$('#submit').disabled=!p.verified||Object.hasOwn(state.fixtures,p.id);$('#submit').title=$('#submit').disabled?'Chỉ chấm bài có input/output đã đối chiếu và đang dùng dữ liệu gốc.':'';$('#description').scrollTop=0}
function history(){const entries=state.history[current.id]||[];$('#history').innerHTML=entries.length?entries.map(h=>`<div class="history-entry"><span>${esc(new Date(h.at).toLocaleString('vi-VN'))} · ${esc(h.verdict)}</span><pre>${esc(h.code)}</pre></div>`).join(''):'<p class="muted">Chưa có lần chạy nào. Lịch sử 20 lần gần nhất được lưu trên thiết bị này.</p>'}
function setBusy(v){busy=v;$('#run-mode').disabled=v;$('#run').disabled=v;$('#submit').disabled=v||freeMode()||!current.verified||Object.hasOwn(state.fixtures,current.id);$('#run').textContent=v?'Đang chạy…':'▷ Chạy thử'}
function sameValue(a,b){if(a===null||b===null)return a===b;if(typeof a==='number'&&typeof b==='number')return Math.abs(a-b)<=1e-7*Math.max(1,Math.abs(a),Math.abs(b));return String(a)===String(b)}
function compare(actual,expected,ordered){if(actual.columns.length!==expected.columns.length||actual.values.length!==expected.values.length)return false;const rowEq=(a,b)=>a.length===b.length&&a.every((v,i)=>sameValue(v,b[i]));if(ordered)return actual.values.every((r,i)=>rowEq(r,expected.values[i]));const unused=[...expected.values];for(const row of actual.values){const index=unused.findIndex(r=>rowEq(row,r));if(index<0)return false;unused.splice(index,1)}return true}
function run(submit=false){if(busy)return;const p=current,code=$('#code').value,setup=freeMode()?'':(state.fixtures[p.id]??p.setup);if(!setup&&!freeMode()){showTab('data');toast('Bài này chưa có input. Nhập CREATE TABLE / INSERT để chạy thử.');return}if(submit&&(!p.verified||Object.hasOwn(state.fixtures,p.id)))return;setBusy(true);$('#result').innerHTML='<p class="muted">Đang khởi tạo cơ sở dữ liệu riêng cho lần chạy này…</p>';const start=performance.now();worker=new Worker('sql-worker.js');const thisWorker=worker;let timer=setTimeout(()=>finish({ok:false,error:'Truy vấn vượt giới hạn 5 giây. Hãy kiểm tra điều kiện JOIN hoặc giảm dữ liệu.'}),5000);
 function finish(data){if(worker!==thisWorker)return;clearTimeout(timer);thisWorker.terminate();worker=null;setBusy(false);$('#execution-time').textContent=Math.round(performance.now()-start)+' ms';let verdict;
 if(!data.ok){verdict='Lỗi thực thi';$('#result').innerHTML=`<div class="verdict fail">Không thể thực thi SQL</div><pre style="white-space:pre-wrap;font-size:11px">${esc(data.error)}</pre><p class="muted">Engine SQLite: một số cú pháp MySQL trong lời giải chưa được hỗ trợ.</p>`}
 else{const r=data.result[0]||{columns:[],values:[]};if(submit){const pass=compare(r,p.expected,/\bORDER\s+BY\b/i.test(p.answer));verdict=pass?'Vượt ví dụ':'Chưa khớp ví dụ';if(pass){state.solved[p.id]=true;updateProgress();renderList()}$('#result').innerHTML=`<div class="verdict ${pass?'':'fail'}">${pass?'✓ Vượt dữ liệu ví dụ':'× Kết quả chưa khớp ví dụ'}<br><small>1 bộ dữ liệu công khai · Không phải test ẩn DBPTIT</small></div><div class="result-label">KẾT QUẢ CỦA BẠN · ${r.values.length} dòng</div>${table(r)}${pass?'':`<div class="result-label">KẾT QUẢ MONG MUỐN</div>${table(p.expected)}`}`}
 else{verdict='Chạy thành công';$('#result').innerHTML=`<div class="verdict info">✓ Chạy thành công · ${data.result.reduce((n,t)=>n+t.values.length,0)} dòng${freeMode()?' · SQL tự do':Object.hasOwn(state.fixtures,p.id)?' · Dữ liệu tự nhập':''}</div>${data.result.map(t=>(t.name?'<div class="result-label">'+esc(t.name)+'</div>':'')+table(t)).join('')||'<p class="muted">Câu lệnh đã thực thi, không có bảng kết quả.</p>'}<p class="muted">Chạy thử chỉ hiển thị kết quả; chọn Nộp ví dụ để đối chiếu nếu bài có hỗ trợ.</p>`}}
 state.history[p.id]=[{at:Date.now(),code,verdict},...(state.history[p.id]||[])].slice(0,20);persist();if(activeTab==='history')history();
 }
 worker.onmessage=e=>finish(e.data);worker.onerror=e=>finish({ok:false,error:e.message||'Không tải được SQL engine.'});worker.postMessage({setup,code,free:freeMode()})}
$('#code').oninput=()=>{if(!current)return;state.drafts[freeMode()?'_free':current.id]=$('#code').value;persist();lineNumbers()};$('#code').onscroll=()=>$('#line-numbers').scrollTop=$('#code').scrollTop;$('#code').onkeydown=e=>{if(e.key==='Tab'){e.preventDefault();const a=e.target.selectionStart,b=e.target.selectionEnd;e.target.setRangeText('  ',a,b,'end');$('#code').oninput()}if((e.ctrlKey||e.metaKey)&&e.key==='Enter'){e.preventDefault();run()}};
$('#run-mode').onchange=()=>{$('#code').value=freeMode()?(state.drafts._free??'-- SQL tự do: chạy nhiều câu lệnh trên CSDL trống mỗi lần\nCREATE TABLE demo (id INTEGER, name TEXT);\nINSERT INTO demo VALUES (1, \'Xin chào SQL!\');\nSELECT * FROM demo;'):(state.drafts[current.id]??defaultCode(current));lineNumbers();setBusy(false);toast(freeMode()?'SQL tự do: hỗ trợ CREATE, INSERT, UPDATE, DELETE và SELECT. CSDL mới mỗi lần chạy.':'Đã chọn dữ liệu bài tập')};$('#run').onclick=()=>run();$('#submit').onclick=()=>run(true);$$('.tabs button').forEach(b=>b.onclick=()=>showTab(b.dataset.tab));['search','difficulty','kind','ready'].forEach(id=>$('#'+id).addEventListener('input',renderList));$('#prev').onclick=()=>select(problems[(current.number-2+problems.length)%problems.length].id);$('#next').onclick=()=>select(problems[current.number%problems.length].id);$('#random').onclick=()=>{const pool=problems.filter(p=>p.verified);select(pool[Math.floor(Math.random()*pool.length)].id)};$('#reset-code').onclick=()=>{const key=freeMode()?'_free':current.id;state.drafts[key]=freeMode()?'-- Nhập SQL tự do. CSDL trống mỗi lần chạy.\nSELECT 1 AS hello;':defaultCode(current);$('#code').value=state.drafts[key];persist();lineNumbers();toast('Đã đặt lại code')};$('#save-fixture').onclick=()=>{state.fixtures[current.id]=$('#fixture').value;persist();$('#submit').disabled=true;toast('Đã áp dụng dữ liệu tự nhập. Chọn Chạy thử để thực thi.')};$('#reset-fixture').onclick=()=>{delete state.fixtures[current.id];persist();$('#fixture').value=current.setup;$('#submit').disabled=freeMode()||!current.verified;toast('Đã khôi phục dữ liệu ví dụ gốc')};$('#copy-solution').onclick=async()=>{try{await navigator.clipboard.writeText(current.answer);toast('Đã sao chép lời giải')}catch{toast('Hãy chọn và sao chép nội dung lời giải.')}};$('#all-nav').onclick=()=>{onlySolved=false;$('#all-nav').classList.add('active');$('#saved-nav').classList.remove('active');renderList()};$('#saved-nav').onclick=()=>{onlySolved=true;$('#saved-nav').classList.add('active');$('#all-nav').classList.remove('active');renderList()};document.addEventListener('keydown',e=>{if(e.key==='/'&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)){e.preventDefault();$('#search').focus()}});window.addEventListener('hashchange',()=>{if(location.hash.slice(1)!==current?.id)select(location.hash.slice(1))});
fetch('problems.json').then(r=>{if(!r.ok)throw Error('Không tải được dữ liệu đề');return r.json()}).then(data=>{problems=data;[...new Set(problems.map(p=>p.type))].forEach(t=>$('#kind').insertAdjacentHTML('beforeend',`<option>${esc(t)}</option>`));updateProgress();select(problems.some(p=>p.id===location.hash.slice(1))?location.hash.slice(1):'SQL094')}).catch(e=>{$('#problem-list').textContent=e.message;toast('Không tải được thư viện. Hãy tải lại trang.')});
